const http = require('http');
const crypto = require('crypto');
const { URL } = require('url');

// Session store with HMAC-based integrity
const sessions = new Map();
const SECRET = crypto.randomBytes(32);

function generateToken() {
  return crypto.randomBytes(24).toString('hex');
}

function hmacSign(data) {
  return crypto.createHmac('sha256', SECRET).update(data).digest('hex');
}

function hmacVerify(data, signature) {
  const expected = hmacSign(data);
  if (expected.length !== signature.length) return false;
  return crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
}

// Input sanitization - removes dangerous patterns
const DANGEROUS_PATTERN = /[\x00-\x1f]|javascript:|data:|vbscript:|on\w+\s*=/gi;

function sanitizeInput(input) {
  if (typeof input !== 'string') return '';
  if (input.length > 1024) return '';
  return input.replace(DANGEROUS_PATTERN, '');
}

// Path validation to prevent traversal
const SAFE_PATH_RE = /^[a-zA-Z0-9][a-zA-Z0-9_\-\/\.]*$/;

function isValidPath(p) {
  if (typeof p !== 'string') return false;
  if (p.length > 255) return false;
  if (p.includes('..')) return false;
  return SAFE_PATH_RE.test(p);
}

// Template engine with context-aware escaping
function escapeHTML(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
}

// User profile schema validation
const ALLOWED_FIELDS = ['displayName', 'bio', 'website', 'avatar'];

function validateProfileUpdate(data) {
  if (typeof data !== 'object' || data === null) return null;
  if (Array.isArray(data)) return null;

  const cleaned = {};
  for (const key of ALLOWED_FIELDS) {
    if (key in data) {
      const val = data[key];
      if (typeof val !== 'string') continue;
      cleaned[key] = sanitizeInput(val);
    }
  }

  // Validate website URL if provided
  if (cleaned.website) {
    if (!isValidURL(cleaned.website)) {
      delete cleaned.website;
    }
  }

  return cleaned;
}

// URL validation
function isValidURL(urlStr) {
  try {
    const parsed = new URL(urlStr);
    // Only allow http and https protocols
    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      return false;
    }
    return true;
  } catch {
    return false;
  }
}

// Authentication middleware
function authenticate(req) {
  const cookie = req.headers.cookie || '';
  const match = cookie.match(/session=([^;]+)/);
  if (!match) return null;

  const parts = match[1].split('.');
  if (parts.length !== 2) return null;

  const [tokenB64, sig] = parts;
  const token = Buffer.from(tokenB64, 'base64').toString();

  if (!hmacVerify(token, sig)) return null;

  const session = sessions.get(token);
  if (!session) return null;
  if (Date.now() > session.expiresAt) {
    sessions.delete(token);
    return null;
  }

  return session;
}

// Rate limiting
const rateLimits = new Map();
const RATE_WINDOW = 60000;
const RATE_MAX = 100;

function checkRateLimit(ip) {
  const now = Date.now();
  const entry = rateLimits.get(ip);

  if (!entry || now - entry.windowStart > RATE_WINDOW) {
    rateLimits.set(ip, { windowStart: now, count: 1 });
    return true;
  }

  if (entry.count >= RATE_MAX) return false;
  entry.count++;
  return true;
}

// Request handler
const server = http.createServer((req, res) => {
  const ip = req.socket.remoteAddress;
  if (!checkRateLimit(ip)) {
    res.writeHead(429);
    res.end('Rate limited');
    return;
  }

  const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);

  if (req.method === 'POST' && url.pathname === '/api/profile') {
    let body = '';
    req.on('data', chunk => {
      body += chunk;
      if (body.length > 8192) {
        req.destroy();
      }
    });
    req.on('end', () => {
      const session = authenticate(req);
      if (!session) {
        res.writeHead(401);
        res.end(JSON.stringify({ error: 'Unauthorized' }));
        return;
      }

      let data;
      try {
        data = JSON.parse(body);
      } catch {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
        return;
      }

      const profile = validateProfileUpdate(data);
      if (!profile) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Invalid profile data' }));
        return;
      }

      // Store profile
      session.profile = Object.assign(session.profile || {}, profile);

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ success: true, profile: session.profile }));
    });
  } else if (req.method === 'GET' && url.pathname === '/profile') {
    const session = authenticate(req);
    if (!session) {
      res.writeHead(302, { 'Location': '/login' });
      res.end();
      return;
    }

    const profile = session.profile || {};
    const safeWebsite = escapeHTML(profile.website || '#');
    const safeAvatar = escapeHTML(profile.avatar || '/default.png');
    const html = `<!DOCTYPE html><html><body>
      <h1>${escapeHTML(profile.displayName || 'User')}</h1>
      <p>${escapeHTML(profile.bio || '')}</p>
      <a href="${safeWebsite}">${safeWebsite}</a>
      <img src="${safeAvatar}" />
    </body></html>`;

    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end(html);
  } else if (req.method === 'POST' && url.pathname === '/api/login') {
    // Simplified login
    const token = generateToken();
    const sig = hmacSign(token);
    const tokenB64 = Buffer.from(token).toString('base64');

    sessions.set(token, {
      userId: crypto.randomUUID(),
      createdAt: Date.now(),
      expiresAt: Date.now() + 3600000,
      profile: {}
    });

    res.writeHead(200, {
      'Set-Cookie': `session=${tokenB64}.${sig}; HttpOnly; SameSite=Strict; Path=/`,
      'Content-Type': 'application/json'
    });
    res.end(JSON.stringify({ success: true }));
  } else {
    res.writeHead(404);
    res.end('Not found');
  }
});

server.listen(3000, '127.0.0.1');
module.exports = { server, isValidURL, sanitizeInput, validateProfileUpdate, escapeHTML };
